// Generated by transition.sh — the bootstrap for a converted VS Code extension.
//
// Load order (see manifest.json): contributes.js -> vscode-shim.js ->
// extension.js -> this file. It restores saved state, builds the shim, runs the
// original module's activate(), then exposes the extension's commands through a
// Tab Sage launcher menu and keyboard shortcuts.
(function () {
  var meta = window.__TS_VSC;
  if (!meta) {
    console.error("[transition] contributes.js did not load — nothing to start.");
    return;
  }

  var guard = "__tsVsc_" + String(meta.id).replace(/[^A-Za-z0-9]/g, "_");
  if (window[guard]) return;
  window[guard] = true;

  var T = typeof tabsage !== "undefined" ? tabsage : null;
  var UI = typeof TabSageUI !== "undefined" ? TabSageUI : null;
  var STATE_KEY = "__vsc_state";

  var state = { config: {}, globalState: {}, workspaceState: {}, secrets: {} };
  var saveTimer = null;

  // tabsage.storage is async and VS Code's configuration reads are sync, so the
  // whole state bag is read once up front and written back on a short debounce.
  function persist() {
    if (!T || !T.storage || !T.storage.setJSON) return;
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = setTimeout(function () {
      saveTimer = null;
      Promise.resolve(T.storage.setJSON(STATE_KEY, state)).catch(function (e) {
        console.error("[" + meta.name + "] could not save state", e);
      });
    }, 250);
  }

  function loadState() {
    if (!T || !T.storage || !T.storage.getJSON) return Promise.resolve();
    return Promise.resolve(T.storage.getJSON(STATE_KEY))
      .then(function (saved) {
        if (!saved || typeof saved !== "object") return;
        ["config", "globalState", "workspaceState", "secrets"].forEach(function (k) {
          if (saved[k] && typeof saved[k] === "object") state[k] = saved[k];
        });
      })
      .catch(function (e) {
        console.warn("[" + meta.name + "] could not read saved state", e);
      });
  }

  function fail(what, e) {
    console.error("[" + meta.name + "] " + what, e);
    if (UI) UI.toast(meta.name + ": " + what, { variant: "danger" });
  }

  loadState().then(start);

  function start() {
    var shim;
    try {
      shim = window.__tsVscCreateShim({ meta: meta, state: state, persist: persist });
    } catch (e) {
      fail("could not build the vscode shim", e);
      return;
    }

    var loader = window.__tsVscCreateLoader(shim.vscode);
    var exports = null;
    try {
      exports = loader.load(meta.entry);
    } catch (e) {
      fail("could not load " + meta.entry + ".js", e);
      return;
    }

    if (exports && typeof exports.activate === "function") {
      try {
        Promise.resolve(exports.activate(shim.context)).catch(function (e) {
          fail("activate() rejected", e);
        });
      } catch (e) {
        fail("activate() threw", e);
      }
    } else {
      console.warn(
        "[" + meta.name + "] the converted module exports no activate(); commands may not be registered.",
      );
    }

    console.log(
      "[" + meta.name + "] converted extension ready on " + location.href,
    );

    wireLauncher(shim);
    wireShortcuts(shim);

    window.addEventListener("pagehide", function () {
      try {
        (shim.context.subscriptions || []).forEach(function (d) {
          if (d && typeof d.dispose === "function") d.dispose();
        });
        if (exports && typeof exports.deactivate === "function") exports.deactivate();
      } catch (e) {
        /* teardown is best effort */
      }
    });
  }

  // The VS Code command palette has no Tab Sage equivalent, so contributed
  // commands become a corner launcher menu.
  function wireLauncher(shim) {
    var commands = meta.commands || [];
    if (!commands.length) return;
    if (!UI) {
      console.warn(
        "[" + meta.name + "] the UI Kit is not loaded, so the command menu is unavailable. Run commands from other code with vscode.commands.executeCommand.",
      );
      return;
    }
    UI.launcher({
      label: meta.name,
      icon: "puzzle",
      corner: meta.corner || "bottom-right",
      title: meta.name + " commands",
      menu: commands.map(function (c) {
        return {
          label: c.category ? c.category + ": " + c.title : c.title,
          icon: "sparkle",
          onClick: function () {
            shim.executeCommand(c.command);
          },
        };
      }),
    });
  }

  function wireShortcuts(shim) {
    var keys = meta.keybindings || [];
    if (!keys.length || !T || !T.shortcuts || !T.shortcuts.register) return;
    keys.forEach(function (k) {
      try {
        T.shortcuts.register(k.accelerator, function () {
          shim.executeCommand(k.command);
        });
      } catch (e) {
        console.warn(
          "[" + meta.name + "] could not register " + k.accelerator + ": " + e.message,
        );
      }
    });
  }
})();
